os-fifo-page-faults.solution:
from collections import deque

def fifo_faults(refs, frames):
    if frames == 0:
        return len(refs)
    mem, order, faults = set(), deque(), 0
    for p in refs:
        if p in mem:
            continue
        faults += 1
        if len(mem) == frames:
            mem.discard(order.popleft())
        mem.add(p)
        order.append(p)
    return faults

os-lru-page-faults.solution:
from collections import OrderedDict

def lru_faults(refs, frames):
    if frames == 0:
        return len(refs)
    mem, faults = OrderedDict(), 0
    for p in refs:
        if p in mem:
            mem.move_to_end(p)
            continue
        faults += 1
        if len(mem) == frames:
            mem.popitem(last=False)
        mem[p] = True
    return faults

os-optimal-page-faults.solution:
import heapq

def optimal_faults(refs, frames):
    if frames == 0:
        return len(refs)
    n = len(refs)
    INF = n + 1
    nxt, seen = [INF] * n, {}
    for i in range(n - 1, -1, -1):
        nxt[i] = seen.get(refs[i], INF)
        seen[refs[i]] = i
    cur, heap, faults = {}, [], 0
    for i, p in enumerate(refs):
        if p not in cur:
            faults += 1
            if len(cur) == frames:
                while True:
                    d, q = heapq.heappop(heap)
                    if cur.get(q) == -d:
                        del cur[q]
                        break
        cur[p] = nxt[i]
        heapq.heappush(heap, (-nxt[i], p))
    return faults

os-clock-page-faults.solution:
def clock_replace(refs, frames):
    slots = [-1] * frames
    rbit = [0] * frames
    where = {}
    hand = faults = 0
    for p in refs:
        if p in where:
            rbit[where[p]] = 1
            continue
        faults += 1
        while slots[hand] != -1 and rbit[hand]:
            rbit[hand] = 0
            hand = (hand + 1) % frames
        if slots[hand] != -1:
            del where[slots[hand]]
        slots[hand] = p
        rbit[hand] = 1
        where[p] = hand
        hand = (hand + 1) % frames
    return [faults, slots]

os-aging-page-replacement.solution:
def aging(ticks, pages, bits):
    counters = [0] * pages
    top = 1 << (bits - 1)
    for tick in ticks:
        touched = set(tick)
        for p in range(pages):
            counters[p] >>= 1
            if p in touched:
                counters[p] |= top
    victim = min(range(pages), key=lambda p: (counters[p], p))
    return [counters, victim]

os-working-set-size.solution:
def working_set_sizes(refs, k):
    count, out = {}, []
    for t, p in enumerate(refs):
        count[p] = count.get(p, 0) + 1
        if t >= k:
            old = refs[t - k]
            count[old] -= 1
            if count[old] == 0:
                del count[old]
        out.append(len(count))
    return out

os-two-level-translation.solution:
def translate(vaddr, page_dir, offset_bits, pt_bits):
    offset = vaddr & ((1 << offset_bits) - 1)
    t = (vaddr >> offset_bits) & ((1 << pt_bits) - 1)
    d = vaddr >> (offset_bits + pt_bits)
    if d >= len(page_dir) or page_dir[d] is None:
        return -1
    table = page_dir[d]
    if t >= len(table) or table[t] is None:
        return -1
    return (table[t] << offset_bits) | offset

os-tlb-simulation.solution:
from collections import OrderedDict

def tlb_sim(addresses, page_size, tlb_size):
    tlb = OrderedDict()
    hits = misses = 0
    for a in addresses:
        vpn = a // page_size
        if vpn in tlb:
            hits += 1
            tlb.move_to_end(vpn)
        else:
            misses += 1
            if tlb_size == 0:
                continue
            if len(tlb) == tlb_size:
                tlb.popitem(last=False)
            tlb[vpn] = True
    return [hits, misses]

os-first-fit.solution:
def first_fit(holes, requests):
    free = list(holes)
    out = []
    for r in requests:
        for i, h in enumerate(free):
            if h >= r:
                free[i] -= r
                out.append(i)
                break
        else:
            out.append(-1)
    return out

os-best-fit.solution:
def best_fit(holes, requests):
    free = list(holes)
    out = []
    for r in requests:
        best = -1
        for i, h in enumerate(free):
            if h >= r and (best == -1 or h < free[best]):
                best = i
        if best != -1:
            free[best] -= r
        out.append(best)
    return out

os-buddy-allocator.solution:
def buddy(total, ops):
    free = {}
    size = 1
    while size <= total:
        free[size] = set()
        size *= 2
    free[total].add(0)
    used, out = {}, []
    for op, x in ops:
        if op == "alloc":
            need = 1
            while need < x:
                need *= 2
            size = need
            while size <= total and not free[size]:
                size *= 2
            if size > total:
                out.append(-1)
                continue
            addr = min(free[size])
            free[size].discard(addr)
            while size > need:
                size //= 2
                free[size].add(addr + size)
            used[addr] = need
            out.append(addr)
        else:
            if x not in used:
                out.append(-1)
                continue
            size, addr = used.pop(x), x
            while size < total and (addr ^ size) in free[size]:
                free[size].discard(addr ^ size)
                addr = min(addr, addr ^ size)
                size *= 2
            free[size].add(addr)
            out.append(size)
    return out

