os-disk-look.solution:
def disk_look(head, requests, direction):
    here = [c for c in requests if c == head]
    up = sorted(c for c in requests if c > head)
    down = sorted((c for c in requests if c < head), reverse=True)
    return here + (up + down if direction == "up" else down + up)

os-inode-block-lookup.solution:
def block_path(block_no, direct, n):
    if block_no < direct:
        return [0, block_no]
    b = block_no - direct
    if b < n:
        return [1, b]
    b -= n
    if b < n * n:
        return [2, b // n, b % n]
    b -= n * n
    if b < n ** 3:
        return [3, b // (n * n), (b // n) % n, b % n]
    return []

os-fat-chain.solution:
def fat_chain(fat, start):
    chain, seen = [], set()
    b = start
    while b != -1:
        if b < 0 or b >= len(fat) or b in seen:
            return None
        seen.add(b)
        chain.append(b)
        b = fat[b]
    return chain

os-raid-parity.solution:
def raid_recover(stripe):
    blocks = [b for b in stripe if b is not None]
    if not blocks:
        return []
    out = [0] * len(blocks[0])
    for b in blocks:
        for i, v in enumerate(b):
            out[i] ^= v
    return out

os-free-bitmap.solution:
def find_free_run(bitmap, n):
    run = 0
    for byte_no, byte in enumerate(bitmap):
        if byte == 0 and run + 8 < n:
            run += 8
            continue
        for bit in range(8):
            if byte >> bit & 1:
                run = 0
            else:
                run += 1
                if run == n:
                    return byte_no * 8 + bit - n + 1
    return -1

os-unix-permissions.solution:
def can_access(mode, owner, group, uid, gids, want):
    bit = {"r": 4, "w": 2, "x": 1}
    if uid == 0:
        return "x" not in want or bool(mode & 0o111)
    if uid == owner:
        perms = (mode >> 6) & 7
    elif group in gids:
        perms = (mode >> 3) & 7
    else:
        perms = mode & 7
    return all(perms & bit[c] for c in want)

os-bankers-safe-sequence.checker:
def check(args, got, expected):
    available, allocation, maximum = args
    n = len(allocation)
    if not expected:
        return got == []
    if not isinstance(got, list) or sorted(got) != list(range(n)):
        return False
    work = list(available)
    for i in got:
        for j in range(len(work)):
            if maximum[i][j] - allocation[i][j] > work[j]:
                return False
        for j in range(len(work)):
            work[j] += allocation[i][j]
    return True

