os-deadlock-detection.solution:
def deadlocked(holds, wants):
    n = len(wants)
    state = [0] * n          # 0 unknown, 1 on current path, 2 fine, 3 deadlocked
    for s in range(n):
        if state[s]:
            continue
        path, p = [], s
        while p != -1 and state[p] == 0:
            state[p] = 1
            path.append(p)
            r = wants[p]
            p = -1 if r == -1 else holds[r]
        if p == -1:
            verdict = 2
        elif state[p] == 1:
            verdict = 3
        else:
            verdict = state[p]
        for q in path:
            state[q] = verdict
    return [p for p in range(n) if state[p] == 3]

os-dining-philosophers.solution:
def dining(n, schedule, ordered):
    owner = [-1] * n
    held = [0] * n
    meals = [0] * n
    for p in schedule:
        first, second = p, (p + 1) % n
        if ordered and first > second:
            first, second = second, first
        if held[p] == 0:
            if owner[first] == -1:
                owner[first] = p
                held[p] = 1
        elif held[p] == 1:
            if owner[second] == -1:
                owner[second] = p
                held[p] = 2
        else:
            owner[first] = owner[second] = -1
            held[p] = 0
            meals[p] += 1
    return [meals, all(h == 1 for h in held)]

os-readers-writers.solution:
def readers_writers(requests, prefer):
    n = len(requests)
    order = sorted(range(n), key=lambda i: (requests[i][0], i))
    start = [0] * n
    waiting, reader_ends = [], []
    writer_end = None
    k = 0
    if n == 0:
        return start
    t = requests[order[0]][0]
    while True:
        reader_ends = [e for e in reader_ends if e > t]
        if writer_end is not None and writer_end <= t:
            writer_end = None
        while k < n and requests[order[k]][0] <= t:
            waiting.append(order[k])
            k += 1
        if writer_end is None:
            writers = [i for i in waiting if requests[i][1] == "W"]
            if prefer == "writers" and writers:
                if not reader_ends:
                    i = writers[0]
                    start[i] = t
                    writer_end = t + requests[i][2]
                    waiting.remove(i)
            else:
                for i in waiting:
                    if requests[i][1] == "R":
                        start[i] = t
                        reader_ends.append(t + requests[i][2])
                waiting = writers
                if waiting and not reader_ends:
                    i = waiting.pop(0)
                    start[i] = t
                    writer_end = t + requests[i][2]
        cands = []
        if k < n:
            cands.append(requests[order[k]][0])
        if waiting:
            if writer_end is not None:
                cands.append(writer_end)
            if reader_ends:
                cands.append(min(reader_ends))
        if not cands:
            break
        t = min(cands)
    return start

os-semaphore-trace.solution:
from collections import deque

def sem_trace(initial, ops):
    value = initial
    queue, blocked, woken = deque(), set(), []
    for pid, op in ops:
        if pid in blocked:
            continue
        if op == "P":
            if value > 0:
                value -= 1
            else:
                queue.append(pid)
                blocked.add(pid)
        else:
            if queue:
                w = queue.popleft()
                blocked.discard(w)
                woken.append(w)
            else:
                value += 1
    return [value, list(queue), woken]
